function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.openingLineStats)) return json.data.openingLineStats;
  if (json && Array.isArray(json.openingLineStats)) return json.openingLineStats;
  return [];
}

const rows = $input.all().flatMap(asArray);
const existing = rows[0] || null;

return [{
  json: {
    exists: !!existing,
    id: existing?.id,
    wonCount: existing?.wonCount || 0,
    lostCount: existing?.lostCount || 0,
  },
}];
